<?php
require __DIR__.'/../app/bootstrap.php'; require_login();
$labels=['computer'=>'پایگاه رایانه','printer'=>'چاپگر','display'=>'نمایشگر','scanner'=>'اسکنر'];$counts=[];$recentByType=[];foreach($labels as $t=>$label){$q=db()->prepare('SELECT COUNT(*) FROM assets WHERE asset_type=?');$q->execute([$t]);$counts[$t]=(int)$q->fetchColumn();$q=db()->prepare('SELECT asset_no,hostname,manufacturer,model,status,updated_at FROM assets WHERE asset_type=? ORDER BY updated_at DESC LIMIT 5');$q->execute([$t]);$recentByType[$t]=$q->fetchAll();}$total=array_sum($counts);$active=(int)db()->query("SELECT COUNT(*) FROM assets WHERE status='active'")->fetchColumn();$repair=(int)db()->query("SELECT COUNT(*) FROM assets WHERE status='repair'")->fetchColumn();$recent=db()->query('SELECT a.action,a.entity_id,a.created_at,u.full_name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 8')->fetchAll();
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($config['app']['name'])?></title><link rel="stylesheet" href="assets/app.css"></head><body><header><a class="brand" href="index.php">سامانه سخت‌افزار</a><nav><a href="assets.php">همه تجهیزات</a><a href="report.php">گزارش‌ها</a><?php if((user()['role']??'')==='admin'):?><a href="directory.php">Active Directory</a><a href="users.php">کاربران برداشت</a><a href="personnel.php">پرسنل</a><a href="audit.php">رویدادها</a><?php endif;?><span class="user-chip"><?=e(user()['full_name']??'')?></span><a href="logout.php">خروج</a></nav></header><main><section class="hero"><div><span class="eyebrow">IHW · INVENTORY & HARDWARE WATCH</span><h1>پایش و مدیریت تجهیزات دانشگاه</h1><p>هر نوع تجهیز پایگاه مستقل، فرم اختصاصی و فهرست جداگانه دارد.</p><div class="hero-actions"><?php if(can_edit_assets()):?><a class="btn light" href="asset_new.php?type=computer">+ ثبت رایانه</a><a class="btn light" href="asset_new.php?type=printer">+ ثبت چاپگر</a><a class="btn light" href="asset_new.php?type=display">+ ثبت نمایشگر</a><a class="btn light" href="asset_new.php?type=scanner">+ ثبت اسکنر</a><?php endif;?></div></div></section><section class="cards"><?php foreach($labels as $k=>$v):?><a class="stat-card" href="assets.php?type=<?=$k?>"><span><?=$v?></span><b><?=$counts[$k]?></b><small>مشاهده پایگاه ←</small></a><?php endforeach;?></section><section class="cards mini-cards"><div class="stat-card"><span>کل تجهیزات</span><b><?=$total?></b></div><div class="stat-card"><span>فعال</span><b><?=$active?></b></div><div class="stat-card"><span>در تعمیر</span><b><?=$repair?></b></div></section><?php foreach($labels as $t=>$label):?><section class="panel"><div class="panel-head"><h2><?=e($label)?></h2><a class="btn small" href="assets.php?type=<?=$t?>">مشاهده همه</a></div><div class="table-wrap"><table><thead><tr><th>شماره اموال</th><th>نام دستگاه</th><th>برند / مدل</th><th>وضعیت</th><th>آخرین تغییر</th><th></th></tr></thead><tbody><?php foreach($recentByType[$t] as $r):?><tr><td><strong><?=e($r['asset_no'])?></strong></td><td><?=e($r['hostname']?:'—')?></td><td><?=e(trim(($r['manufacturer']??'').' '.($r['model']??''))?:'—')?></td><td><span class="badge <?=e($r['status'])?>"><?=e(['active'=>'فعال','repair'=>'تعمیر','retired'=>'اسقاط','lost'=>'مفقود'][$r['status']]??$r['status'])?></span></td><td><?=e($r['updated_at'])?></td><td><a class="btn small" href="asset_view.php?asset_no=<?=urlencode($r['asset_no'])?>">مشاهده</a></td></tr><?php endforeach;?><?php if(!$recentByType[$t]):?><tr><td colspan="6" class="empty">هنوز موردی در این پایگاه ثبت نشده است.</td></tr><?php endif;?></tbody></table></div></section><?php endforeach;?><section class="panel"><div class="panel-head"><h2>آخرین رویدادها</h2><?php if((user()['role']??'')==='admin'):?><a href="audit.php">همه رویدادها</a><?php endif;?></div><div class="table-wrap"><table><thead><tr><th>کاربر</th><th>عملیات</th><th>شناسه</th><th>زمان</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><?=e($r['full_name']?:'سیستم')?></td><td><?=e($r['action'])?></td><td><?=e($r['entity_id'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></tbody></table></div></section></main></body></html>
